#include "logfmt.h"
#include <stdio.h>
#include <string.h>

int logfmt_format(char *out, size_t out_sz, const char *key, const char *val) {
    int n = snprintf(out, out_sz, "%s=%s", key, val);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

int logfmt_copy(char *dst, size_t dst_sz, const char *src) {
    if (dst_sz == 0) return -1;
    strncpy(dst, src, dst_sz - 1);
    dst[dst_sz - 1] = '\0';
    return 0;
}

int logfmt_parse(const char *in, char *key_out, size_t k_sz, char *val_out, size_t v_sz) {
    const char *eq = strchr(in, '=');
    if (!eq) return -1;
    size_t klen = (size_t)(eq - in);
    if (klen >= k_sz) klen = k_sz - 1;
    strncpy(key_out, in, klen);
    key_out[klen] = '\0';

    const char *val_start = eq + 1;
    if (*val_start == '"') {
        const char *quote_end = strchr(val_start + 1, '"');
        if (!quote_end) return -1;
        size_t vlen = (size_t)(quote_end - val_start - 1);
        if (vlen >= v_sz) vlen = v_sz - 1;
        strncpy(val_out, val_start + 1, vlen);
        val_out[vlen] = '\0';
        return 0;
    }

    size_t vlen = strlen(val_start);
    if (vlen >= v_sz) vlen = v_sz - 1;
    strncpy(val_out, val_start, vlen);
    val_out[vlen] = '\0';
    return 0;
}

int logfmt_format_ts(char *out, size_t out_sz, const char *key, const char *val, long ts) {
    int n = snprintf(out, out_sz, "%s=%s ts=%ld", key, val, ts);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

size_t logfmt_len(const char *key, const char *val) {
    return strlen(key) + strlen(val) + 3; // +2 for '=' and one for null terminator
}

size_t logfmt_len_ts(const char *key, const char *val, long ts) {
    return strlen(key) + strlen(val) + 10 + 3; // +9 for ' ts=' and one for null terminator
}
